import java.util.*;

public class Main {
    static int steps;

    // Time O(log n), space O(1): every look throws away half of the window.
    static int search(int[] a, int target) {
        int lo = 0, hi = a.length - 1;
        steps = 0;
        while (lo <= hi) {                    // window [lo, hi] still has items
            int mid = lo + (hi - lo) / 2;     // open the "dictionary" in the middle
            steps++;
            if (a[mid] == target) return mid;
            if (a[mid] < target) lo = mid + 1; // target is after mid: drop left half
            else hi = mid - 1;                 // target is before mid: drop right half
        }
        return -1;                            // window is empty: not present
    }

    public static void main(String[] args) {
        int[] a = {2, 5, 8, 12, 16, 23, 38, 56, 72, 91};
        System.out.println("array: " + Arrays.toString(a).replaceAll("[\\[\\],]", ""));
        for (int t : new int[]{23, 7}) {
            int idx = search(a, t);
            System.out.println("search " + t + " -> index " + idx + " in " + steps + " looks");
        }
    }
}

