    const mid = lo + ((hi - lo) >> 1);       // open the "dictionary" in the middle
    steps++;
    if (a[mid] === target) return [mid, steps];
    if (a[mid] < target) lo = mid + 1;       // target is after mid: drop left half
    else hi = mid - 1;                       // target is before mid: drop right half
  }
  return [-1, steps];                        // window is empty: not present
}

