public class Main {
    public static void main(String[] args) {
        // Two valid 32-bit indexes whose sum does not fit in 32 bits.
        int lo = 2000000000, hi = 2100000000;
        System.out.println("lo = " + lo + ", hi = " + hi);

        int bad = (lo + hi) / 2;        // the sum wraps around to a negative number
        int safe = lo + (hi - lo) / 2;  // hi - lo is small, so nothing can overflow
        int shift = (lo + hi) >>> 1;    // unsigned shift reads the wrapped bits as positive
        int signed = (lo + hi) >> 1;    // signed shift keeps the wrong minus sign

        System.out.println("(lo + hi) / 2       = " + bad);
        System.out.println("lo + (hi - lo) / 2  = " + safe);
        System.out.println("(lo + hi) >>> 1     = " + shift);
        System.out.println("(lo + hi) >> 1      = " + signed);
        // Each midpoint costs O(1) time and O(1) space; only the bad one is wrong.
    }
}

