#include <bits/stdc++.h>
using namespace std;

int main() {
    // Two valid 32-bit indexes whose sum does not fit in 32 bits.
    int32_t lo = 2000000000, hi = 2100000000;
    cout << "lo = " << lo << ", hi = " << hi << "\n";

    // Signed overflow is undefined in C++, so add as unsigned to show the wrap safely.
    int32_t wrapped = (int32_t)((uint32_t)lo + (uint32_t)hi);
    int32_t bad = wrapped / 2;                       // the sum wrapped around to a negative number
    int32_t safe = lo + (hi - lo) / 2;               // hi - lo is small, so nothing can overflow
    int32_t shift = (int32_t)((uint32_t)wrapped >> 1); // unsigned shift reads the bits as positive
    int32_t sgn = wrapped >> 1;                      // signed shift keeps the wrong minus sign

    cout << "(lo + hi) / 2       = " << bad << "\n";
    cout << "lo + (hi - lo) / 2  = " << safe << "\n";
    cout << "(lo + hi) >>> 1     = " << shift << "\n";
    cout << "(lo + hi) >> 1      = " << sgn << "\n";
    // Each midpoint costs O(1) time and O(1) space; only the bad one is wrong.
    return 0;
}

