import java.util.*;

public class Main {
    static int checks;

    // Invariant: every index < lo has a[i] < x, every index >= hi has a[i] >= x.
    static boolean invariantHolds(int[] a, int x, int lo, int hi) {
        for (int i = 0; i < lo; i++) if (a[i] >= x) return false;
        for (int i = hi; i < a.length; i++) if (a[i] < x) return false;
        return true;
    }

    // Time O(log n), space O(1) (the invariant check is only for this demo).
    static int lowerBound(int[] a, int x) {
        int lo = 0, hi = a.length;          // half-open window [lo, hi)
        checks = 0;
        while (lo < hi) {
            if (!invariantHolds(a, x, lo, hi)) throw new IllegalStateException("broken");
            checks++;
            int mid = lo + (hi - lo) / 2;
            if (a[mid] < x) lo = mid + 1;   // mid and everything left of it is < x
            else hi = mid;                  // mid is >= x, so it may be the answer
        }
        return lo;                          // lo == hi: first index with a[i] >= x
    }

    public static void main(String[] args) {
        int[] a = {1, 3, 3, 5, 8, 8, 10};
        System.out.println("array: " + Arrays.toString(a).replaceAll("[\\[\\],]", ""));
        for (int x : new int[]{8, 4, 11}) {
            int r = lowerBound(a, x);
            System.out.println("lower bound of " + x + " = " + r + " (invariant held " + checks + " times)");
        }
    }
}

