import java.util.*;

public class Main {
    // Template 1: closed window, moves are mid +/- 1, may end empty.
    static int exact(int[] a, int x) {
        int lo = 0, hi = a.length - 1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (a[mid] == x) return mid;
            if (a[mid] < x) lo = mid + 1; else hi = mid - 1;
        }
        return -1;                       // lo > hi: nothing left to look at
    }

    // Template 2: half-open window, one branch keeps mid, ends with lo == hi.
    static int firstAtLeast(int[] a, int x) {
        int lo = 0, hi = a.length;       // hi = n means "no such index"
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (a[mid] >= x) hi = mid;   // mid could be the answer: keep it
            else lo = mid + 1;
        }
        return lo;
    }

    // Both are O(log n) time and O(1) space.
    public static void main(String[] args) {
        int[] a = {1, 3, 5, 7, 9, 11};
        System.out.println("array: " + Arrays.toString(a).replaceAll("[\\[\\],]", ""));
        for (int x : new int[]{7, 4, 12})
            System.out.println("x = " + x + ": exact index " + exact(a, x)
                    + ", first index with value >= x is " + firstAtLeast(a, x));
    }
}

