// One routine for both ends: on a match, save the index and keep going.
// Time O(log n), space O(1).
int occurrence(const vector<int>& a, int x, bool first) {
    int lo = 0, hi = (int)a.size() - 1, ans = -1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] == x) {
            ans = mid;                    // remember this hit
            if (first) hi = mid - 1;      // an earlier copy may exist on the left
            else lo = mid + 1;            // a later copy may exist on the right
        } else if (a[mid] < x) lo = mid + 1;
        else hi = mid - 1;
    }
    return ans;
}

int main() {
    vector<int> a = {1, 2, 2, 2, 3, 5, 5, 8};
    cout << "array:";
    for (int v : a) cout << " " << v;
    cout << "\n";
    for (int x : {2, 5, 4}) {
        int f = occurrence(a, x, true), l = occurrence(a, x, false);
        int count = f == -1 ? 0 : l - f + 1;   // copies sit next to each other
        cout << "target " << x << ": first " << f << ", last " << l << ", count " << count << "\n";
    }
    return 0;
}

