import java.util.*;

public class Main {
    // Time O(log n) without duplicates, O(n) worst case with them; space O(1).
    static int search(int[] a, int target) {
        int lo = 0, hi = a.length - 1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (a[mid] == target) return mid;
            if (a[lo] == a[mid] && a[mid] == a[hi]) {   // duplicates hide the sorted half
                lo++; hi--;                             // both ends are not the target
            } else if (a[lo] <= a[mid]) {               // left half [lo, mid] is sorted
                if (a[lo] <= target && target < a[mid]) hi = mid - 1;
                else lo = mid + 1;
            } else {                                    // right half [mid, hi] is sorted
                if (a[mid] < target && target <= a[hi]) lo = mid + 1;
                else hi = mid - 1;
            }
        }
        return -1;
    }

    static void show(int[] a, int[] targets) {
        System.out.println("array: " + Arrays.toString(a).replaceAll("[\\[\\],]", ""));
        for (int t : targets) System.out.println("  search " + t + " -> index " + search(a, t));
    }

    public static void main(String[] args) {
        show(new int[]{4, 5, 6, 7, 0, 1, 2}, new int[]{0, 5, 3});
        show(new int[]{2, 2, 2, 0, 2}, new int[]{0, 1});
    }
}

