import java.util.*;

public class Main {
    // Feasibility check: can Koko finish all piles in h hours at this speed? O(n)
    static boolean ok(int[] piles, int h, int speed) {
        long hours = 0;
        for (int p : piles) hours += (p + speed - 1) / speed;   // ceil(p / speed)
        return hours <= h;
    }

    // Time O(n log(maxPile)), space O(1).
    static int minSpeed(int[] piles, int h) {
        int lo = 1, hi = 0;
        for (int p : piles) hi = Math.max(hi, p);   // answer range is [1, max pile]
        while (lo < hi) {                           // find the first speed where ok is true
            int mid = lo + (hi - lo) / 2;
            if (ok(piles, h, mid)) hi = mid;        // works: try something slower
            else lo = mid + 1;                      // too slow: must go faster
        }
        return lo;
    }

    static void show(int[] piles, int h) {
        System.out.println("piles: " + Arrays.toString(piles).replaceAll("[\\[\\],]", "")
                + ", hours: " + h + " -> minimum speed " + minSpeed(piles, h));
    }

    public static void main(String[] args) {
        show(new int[]{3, 6, 7, 11}, 8);
        show(new int[]{30, 11, 23, 4, 20}, 5);
        show(new int[]{30, 11, 23, 4, 20}, 6);
    }
}

