import java.util.*;

public class Main {
    // Greedy: put each cow in the first stall at least d away from the previous cow.
    static int placed(int[] stalls, int d) {
        int count = 1, last = stalls[0];        // first cow goes in the leftmost stall
        for (int i = 1; i < stalls.length; i++)
            if (stalls[i] - last >= d) { count++; last = stalls[i]; }
        return count;
    }

    // Time O(n log n) to sort + O(n log(range)) to search; space O(1) extra.
    public static void main(String[] args) {
        int[] stalls = {1, 2, 8, 4, 9};
        int cows = 3;
        System.out.println("stalls: " + Arrays.toString(stalls).replaceAll("[\\[\\],]", "") + ", cows: " + cows);
        Arrays.sort(stalls);                    // greedy needs left-to-right order
        System.out.println("sorted: " + Arrays.toString(stalls).replaceAll("[\\[\\],]", ""));

        int lo = 1, hi = stalls[stalls.length - 1] - stalls[0], best = 0;
        while (lo <= hi) {                      // find the last distance that is feasible
            int mid = lo + (hi - lo) / 2;
            int c = placed(stalls, mid);
            System.out.println("  distance " + mid + ": greedy places " + c + " cows");
            if (c >= cows) { best = mid; lo = mid + 1; }   // works: try a bigger gap
            else hi = mid - 1;                             // fails: gap is too big
        }
        System.out.println("largest minimum distance = " + best);
    }
}

