import java.util.*;

public class Main {
    // Greedy: how many painters are needed if nobody may paint more than limit?
    static int paintersNeeded(long[] boards, long limit) {
        int painters = 1;
        long load = 0;                           // long: loads can pass 2^31
        for (long b : boards) {
            if (load + b > limit) { painters++; load = 0; }  // start a new painter
            load += b;
        }
        return painters;
    }

    // Time O(n log(sum)), space O(1).
    static long minTime(long[] boards, int k) {
        long lo = 0, hi = 0;
        for (long b : boards) { lo = Math.max(lo, b); hi += b; }  // range [max, sum]
        while (lo < hi) {                        // first limit that k painters can meet
            long mid = lo + (hi - lo) / 2;
            if (paintersNeeded(boards, mid) <= k) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }

    static void show(long[] boards, int k) {
        System.out.println("boards: " + Arrays.toString(boards).replaceAll("[\\[\\],]", "")
                + ", painters: " + k + " -> minimum time " + minTime(boards, k));
    }

    public static void main(String[] args) {
        show(new long[]{10, 20, 30, 40}, 2);
        show(new long[]{2000000000L, 1500000000L, 1000000000L}, 2);  // sum is above int range
    }
}

