  for (const b of boards) {
    if (load + b > limit) { painters++; load = 0; }   // start a new painter
    load += b;
  }
  return painters;
}

// Time O(n log(sum)), space O(1).
// JS numbers are exact up to 2^53, so use Math.floor, not the 32-bit ">> 1".
function minTime(boards, k) {
  let lo = Math.max(...boards);                       // range [max, sum]
  let hi = boards.reduce((s, b) => s + b, 0);
  while (lo < hi) {                                   // first limit that k painters can meet
    const mid = lo + Math.floor((hi - lo) / 2);
    if (paintersNeeded(boards, mid) <= k) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

function show(boards, k) {
  console.log("boards: " + boards.join(" ") + ", painters: " + k + " -> minimum time " + minTime(boards, k));
}

