import java.util.*;

public class Main {
    static final int NEG = Integer.MIN_VALUE, POS = Integer.MAX_VALUE;

    // Time O(log(min(m, n))), space O(1).
    static double median(int[] A, int[] B) {
        if (A.length > B.length) return median(B, A);   // always cut the shorter array
        int m = A.length, n = B.length, half = (m + n + 1) / 2;
        int lo = 0, hi = m;
        while (lo <= hi) {
            int i = lo + (hi - lo) / 2, j = half - i;   // i items from A, j items from B
            int aL = i == 0 ? NEG : A[i - 1], aR = i == m ? POS : A[i];  // sentinels at the edges
            int bL = j == 0 ? NEG : B[j - 1], bR = j == n ? POS : B[j];
            if (aL > bR) hi = i - 1;                    // A gave too many: move the cut left
            else if (bL > aR) lo = i + 1;               // A gave too few: move the cut right
            else {
                int left = Math.max(aL, bL);
                if ((m + n) % 2 == 1) return left;      // odd total: middle item
                return (left + Math.min(aR, bR)) / 2.0; // even total: average of the two middles
            }
        }
        return -1;
    }

    static void show(int[] A, int[] B) {
        System.out.println("A: " + Arrays.toString(A).replaceAll("[\\[\\],]", "") + " | B: "
                + Arrays.toString(B).replaceAll("[\\[\\],]", "")
                + " -> median " + String.format("%.1f", median(A, B)));
    }

    public static void main(String[] args) {
        show(new int[]{1, 3, 8, 9, 15}, new int[]{7, 11, 18, 19, 21, 25});
        show(new int[]{1, 2}, new int[]{3, 4});
    }
}

