public class Main {
    static int tests;

    // Pretend test run: commits before firstBad pass, the rest fail.
    static boolean isBad(int commit, int firstBad) {
        tests++;
        return commit >= firstBad;
    }

    // Time O(log n) test runs, space O(1).
    static int bisect(int n, int firstBad) {
        int lo = 1, hi = n;                   // commit 1 is good, commit n is known bad
        tests = 0;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (isBad(mid, firstBad)) hi = mid;   // bug already present: look earlier
            else lo = mid + 1;                    // still good: bug came later
        }
        return lo;                            // first commit where the test fails
    }

    public static void main(String[] args) {
        int[][] cases = {{1000, 713}, {1000000, 999999}, {16, 1}};
        for (int[] c : cases) {
            int found = bisect(c[0], c[1]);
            // A linear walk would need up to n test runs.
            System.out.println(c[0] + " commits, bug introduced at " + c[1]
                    + " -> found " + found + " after " + tests + " test runs");
        }
    }
}

