public class Main {
    static final int CAP = 200;   // safety cap so the demo cannot hang

    // Epsilon loop: returns how many iterations it ran (CAP means it never finished).
    static int epsilonLoop(double x) {
        double lo = 0, hi = Math.max(1.0, x);
        int it = 0;
        while (hi - lo > 1e-9 && it < CAP) {
            double mid = (lo + hi) / 2;
            if (mid * mid <= x) lo = mid; else hi = mid;   // keep mid, no +1 for reals
            it++;
        }
        return it;
    }

    // Fixed count: 100 halvings always stop. Time O(100) = O(1), space O(1).
    static double sqrtFixed(double x) {
        double lo = 0, hi = Math.max(1.0, x);
        for (int i = 0; i < 100; i++) {
            double mid = (lo + hi) / 2;
            if (mid * mid <= x) lo = mid; else hi = mid;
        }
        return lo;
    }

    static void show(String label, double x) {
        int it = epsilonLoop(x);
        // Near 1e12 neighbouring doubles are about 1e-4 apart, so a 1e-9 gap is unreachable.
        String note = it == CAP ? "never finished (stopped by the cap of " + CAP + ")" : "finished in " + it + " iterations";
        System.out.println("x = " + label + ": fixed 100 iterations give " + String.format("%.6f", sqrtFixed(x))
                + "; epsilon loop " + note);
    }

    public static void main(String[] args) {
        show("2", 2.0);
        show("1e24", 1e24);
    }
}

